const __pageData = JSON.parse('{"title":"Sergey Lavrov","description":"","frontmatter":{"title":"Sergey Lavrov","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["russia","diplomacy","africa","sahel","foreign-policy"],"sources":["raw/badlands-brief-405.md","raw/badlands-brief-7c0.md","raw/badlands-brief-740.md","raw/badlands-brief-c5b.md","raw/badlands-brief-e60.md","raw/badlands-brief-ea5.md","raw/badlands-brief-e3f.md","raw/badlands-brief-f02.md","raw/badlands-news-brief-08e.md","raw/badlands-news-brief-09b.md","raw/badlands-news-brief-19b.md","raw/badlands-news-brief-1e6.md","raw/badlands-news-brief-363.md","raw/badlands-news-brief-433.md","raw/badlands-news-brief-467.md","raw/badlands-news-brief-4bb.md","raw/badlands-news-brief-4a9.md","raw/badlands-news-brief-4cf.md","raw/badlands-news-brief-50a.md","raw/badlands-news-brief-574.md","raw/badlands-news-brief-5c8.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-70a.md","raw/badlands-news-brief-6e5.md","raw/badlands-news-brief-71c.md","raw/badlands-news-brief-713.md","raw/badlands-news-brief-748.md","raw/badlands-news-brief-7a5.md","raw/badlands-news-brief-7b1.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-7b7.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-824.md","raw/badlands-news-brief-860.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/sergey-lavrov.md","filePath":"entities/sergey-lavrov.md","lastUpdated":null}');
